async provisionInternalCalendar(tenantId, blueprint) {
        const setup = await this.internalCalendarService.getSetup(tenantId);
        const ownerProvider = setup.providers[0];
        if (!ownerProvider) {
            throw new common_1.ConflictException('Owner provider was not created');
        }
        await this.internalCalendarService.bootstrapUpdateProvider(tenantId, ownerProvider.id, {
            title: blueprint.providerTitle,
        });
        const providers = [ownerProvider];
        for (let index = 1; index < blueprint.providerCount; index += 1) {
            providers.push(await this.internalCalendarService.bootstrapCreateProvider(tenantId, {
                displayName: `${blueprint.providerTitle} ${index + 1}`,
                title: blueprint.providerTitle,
            }));
        }
        for (const service of blueprint.services) {
            await this.internalCalendarService.bootstrapCreateService(tenantId, {
                name: service.name,
                price: service.price,
                durationMinutes: service.durationMinutes,
            });
        }
        for (const provider of providers) {
            await this.internalCalendarService.bootstrapReplaceWeeklyAvailability(tenantId, provider.id, blueprint.weeklyRules);
        }
    }

